import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to exhibit specific ELA features.
    """
    if x.shape != (3,):
        raise ValueError("Input must be a NumPy array of shape (3,).")

    f = 0.5 * (x[0]**2) + 0.3 * (x[1]**2) + 0.2 * (x[2]**2) + 0.1 * x[0] * x[1] + 0.4 * x[0] + 0.0
    f = 0.015 * (f / 10)
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function.
    """
    if x.ndim != 1 or x.shape[0] != 3:
        raise ValueError("Input must be a 1D array of shape (3,)")

    x = (x + 1.5) / 2.5
    f = 0.6 * np.sum(x**2) + 0.2 * np.sum(x**3) - 0.1 * (x[0] * x[1] + x[1] * x[2])

    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    n = len(x)
    if n != 3:
        raise ValueError("Dimension must be 3.")

    x = (x + 0.2) / 5

    f = 0.3 * (x[0]**2 + x[1]**2 + x[2]**2) + 0.15 * (x[0] * x[1] - x[1] * x[2]) + 0.2 * (np.abs(x[0] - 0.5) + np.abs(x[1] - 0.3) - np.abs(x[2] - 0.7))
    f += 0.1 * np.cos(2 * np.pi * x[0]) * np.exp(-5 * ((x[1] - 0.2)**2 + (x[2] - 0.8)**2))

    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = x / 5
    f = (x[0]**2 + x[1]**2 + x[2]**2) + 0.2 * (x[0] * x[1]) + 0.1 * np.cos(2 * np.pi * (x[0] + x[1] + x[2]))
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.05 * (x[0]**2 + x[1]**2 + x[2]**2) - 0.02 * (x[0] * x[1] + x[1] * x[2] + x[0] * x[2])
    f += 0.1 * np.sin(2 * np.pi * x[0]) + 0.05 * np.sin(4 * np.pi * x[1]) + 0.025 * np.sin(8 * np.pi * x[2])
    f += 0.2 * np.exp(x[0] + 0.5) * (np.abs(x[1] - 1))
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.1 * (x[0]**4 + x[1]**4 + x[2]**4) - 0.05 * (x[0]**2 * x[1]**2)
    f += 0.2 * np.exp(0.5 * x[0]) - 0.1 * np.exp(0.3 * x[1])
    f += 0.1 * np.abs(x[0]) - 0.05 * np.abs(x[1])
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.05 * (x[0]**2 + x[1]**2 + x[2]**2) - 0.02 * (x[0] * x[1] + x[1] * x[2] + x[0] * x[2])
    f += 0.1 * np.sin(2 * np.pi * x[0])
    f += 0.2 * np.exp(x[0] + 0.5) * (np.abs(x[1] - 1))
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.1 * (x[0]**4 + x[1]**4 + x[2]**4) - 0.05 * (x[0]**2 * x[1]**2)
    f += 0.2 * np.exp(1.5 * x[0]) - 0.1 * np.exp(0.8 * x[1])
    f += 0.3 * np.abs(x[0]) - 0.15 * np.abs(x[1])
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.2 * (x[0]**2 + x[1]**2 + x[2]**2) - 0.1 * (x[0] * x[1] + x[1] * x[2])
    f += 0.1 * np.exp(x[0]) - 0.05 * np.exp(x[1]) + 0.01 * x[2] + 1.0
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.1 * (x[0]**4 + x[1]**4 + x[2]**4) - 0.05 * (x[0]**2 * x[1]**2) + 0.2 * np.exp(1.5 * x[0]) - 0.1 * np.exp(0.8 * x[1])
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.5 * np.sin(x[0]) + 0.4 * np.cos(x[1]) + 0.3 * x[2]
    f += 0.1 * x[0] * x[1] + 0.2 * x[1] * x[2]
    f += 0.05 * np.exp(-(x[0]**2 + x[1]**2)) - 0.08 * np.arctan(x[2])
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.05 * (x[0]**3 + x[1]**3 + x[2]**3) + 0.1 * np.sin(x[0] + x[1]) - 0.05 * np.cos(x[1] + x[2]) + 0.2 * np.abs(x[0] - 0.5) - 0.1 * np.abs(x[1] + 0.5)
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.1 * (x[0]**4 + x[1]**4 + x[2]**4) - 0.05 * (x[0]**2 * x[1]**2 + x[1]**2 * x[2]**2) + 0.02 * (x[0] * x[1] * x[2])
    f += 0.2 * np.exp(1.5 * x[0]) - 0.1 * np.exp(0.8 * x[1])
    f += 0.05 * np.log(1 + np.exp(5 * (x[2] - 1))) #log-sigmoid to target skewness
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.1 * (x[0]**4 + x[1]**4 + x[2]**4) - 0.05 * (x[0] * x[1] + x[1] * x[2])
    f += 0.2 * np.exp(0.5 * x[0])
    f += 0.03 * np.arctan(2 * x[2])
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.1 * (x[0]**4 + x[1]**4 + x[2]**4) + 0.2 * np.exp(1.5 * x[0]) - 0.1 * np.exp(0.8 * x[1])
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.1 * np.sum(x**4) - 0.05 * np.sum(x[:2]**2) + 0.2 * np.exp(x[0])
    f += 0.3 * np.abs(x[1]) + 0.03 * np.arctan(5*x[2])
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.1 * (x[0]**2 + x[1]**2 + x[2]**2)
    f += 0.2 * np.exp(0.5 * (x[0] + 0.5))
    f += 0.3 * np.abs(x[1] - 0.2)
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.1 * (x[0]**4 + x[1]**4 + x[2]**4) - 0.05 * (x[0]**2 * x[1]**2)
    f += 0.2 * np.exp(1.5 * (x[0] + 0.2)) - 0.1 * np.exp(0.8 * x[1])
    f += 0.3 * np.abs(x[0] - 0.5) - 0.15 * np.abs(x[1] + 0.3)
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.5 * (x[0]**2 + x[1]**2 + x[2]**2) # Quadratic bowl
    f += 0.2 * np.sin(2 * x[0] + np.pi/4) + 0.15 * np.sin(4 * x[1] - np.pi/6 ) + 0.1 * np.sin(x[2] - np.pi/3) # Sine waves
    f -= 0.5 / (1 + (x[0] - 0.5)**2 + (x[1] + 1)**2 + (x[2] - 0.25)**2) # Reciprocal term
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.1 * (x[0]**3 + x[1]**3 + x[2]**3) + 0.05 * (x[0] * x[1] * x[2])
    f += 0.2 * np.exp(x[0]) - 0.1 * np.sinh(x[1]) + 0.05* x[2]
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    f = 0.1 * (x[0]**4 + x[1]**4 + x[2]**4) - 0.05 * (x[0]**2 * x[1]**2)
    f += 0.2 * np.exp(1.2 * x[0]) - 0.1 * np.exp(0.6 * x[1])
    f += 0.3 * np.abs(x[0]) - 0.15 * np.abs(x[1]) + 0.05 * (x[2]**2)
    return float(f)
